"use client";
import {useEffect,useRef,useState} from 'react';
import {hotelClient,hotelRpc} from '@/lib/pilot';
import type {HandoffScope} from '@/lib/cashier-handoff';
import {readBankAccounts} from '@/lib/cashier-bank-deposits';
type Request={request:string;account:string;reason:string};
export function CashierDepositAccountAssign({scope,deposit,assigned,onSaved}:{scope:HandoffScope;deposit:string;assigned:boolean;onSaved:()=>void}){
 const [cancelConfirmed,setCancelConfirmed]=useState(false),[accounts,setAccounts]=useState<ReturnType<typeof readBankAccounts>|null>(null),[pending,setPending]=useState<Request|null>(null),[busy,setBusy]=useState(false),[error,setError]=useState(''),[message,setMessage]=useState('');const alive=useRef(false),lock=useRef(false);const key='irp.deposit.assignment.v1:'+ [scope.tenant,scope.property,scope.actor,deposit].join(':');
 function read():Request|null{const raw=sessionStorage.getItem(key);if(raw===null)return null;const r=JSON.parse(raw);if(!r||typeof r.request!=='string'||!/^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$/.test(r.request)||typeof r.account!=='string'||!/^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$/.test(r.account)||typeof r.reason!=='string'||r.reason!==r.reason.trim()||r.reason.length<4||r.reason.length>500||/[\x00-\x1f\x7f]/.test(r.reason))throw Error('Invalid pending assignment. Preserve it for recovery.');return {request:r.request,account:r.account,reason:r.reason}}
 useEffect(()=>{alive.current=true;try{setPending(read())}catch(e){setError(e instanceof Error?e.message:'Unable to recover assignment.')}return()=>{alive.current=false}},[key]);
 async function identify(){const u=await hotelClient().auth.getUser();if(u.error||u.data.user?.id!==scope.actor)throw Error('Sign-in changed. Reopen deposits.');}
 async function run(r:Request,status=false){if(lock.current)return;lock.current=true;setBusy(true);setError('');setMessage('');try{await identify();if(!alive.current)return;const prior=read();if(prior&&JSON.stringify(prior)!==JSON.stringify(r))throw Error('Recover the pending assignment first.');const encoded=JSON.stringify(r);sessionStorage.setItem(key,encoded);if(sessionStorage.getItem(key)!==encoded)throw Error('Unable to preserve assignment recovery.');read();setPending(r);
 const value=await hotelRpc(status?'cashier_deposit_account_assignment_status':'assign_cashier_deposit_account',status?{p_tenant:scope.tenant,p_property:scope.property,p_request:r.request}:{p_tenant:scope.tenant,p_property:scope.property,p_deposit:deposit,p_account:r.account,p_request:r.request,p_reason:r.reason,p_confirmed:true});await identify();if(!alive.current)return;
 const v=value as Record<string,unknown>;if(!v||v.schema_version!==1||v.tenant_id!==scope.tenant||v.property_id!==scope.property||v.actor_id!==scope.actor||v.request_id!==r.request)throw Error('Assignment receipt scope changed.');let receipt=v;
 if(status){if(typeof v.found!=='boolean')throw Error('Invalid assignment recovery.');if(!v.found){if(v.result!==null)throw Error('Invalid assignment recovery.');if(!assigned){setMessage('No saved assignment found. Retry the original request.');return}sessionStorage.removeItem(key);if(sessionStorage.getItem(key)!==null)throw Error('Unable to clear pending assignment.');setPending(null);setMessage('Another assignment is already recorded. Your unsaved request was cleared.');return}receipt=v.result as Record<string,unknown>}
 if(!receipt||receipt.schema_version!==1||receipt.tenant_id!==scope.tenant||receipt.property_id!==scope.property||receipt.actor_id!==scope.actor||receipt.request_id!==r.request||receipt.deposit_id!==deposit||receipt.reason!==r.reason||receipt.account_id!==r.account||receipt.bank_verified!==false||receipt.journal_posted!==false||typeof receipt.replayed!=='boolean'||typeof receipt.created_at!=='string')throw Error('Assignment receipt does not match the request.');
 sessionStorage.removeItem(key);if(sessionStorage.getItem(key)!==null)throw Error('Unable to clear pending assignment.');setPending(null);setMessage('Bank account assigned. The original deposit record is retained.');onSaved();
 }catch(e){if(alive.current)setError(e instanceof Error?e.message:'Assignment interrupted. Check the saved result.')}finally{lock.current=false;if(alive.current)setBusy(false)}}
 async function load(next=false){if(lock.current)return;lock.current=true;setBusy(true);setError('');try{await identify();if(!alive.current)return;const before=next?accounts?.next:null;if(next&&!before)return;const parsed=readBankAccounts(await hotelRpc('cashier_bank_accounts',{p_tenant:scope.tenant,p_property:scope.property,p_before:before??null}),scope,before??null);await identify();if(alive.current)setAccounts(parsed)}catch(e){if(alive.current)setError(e instanceof Error?e.message:'Unable to load accounts.')}finally{lock.current=false;if(alive.current)setBusy(false)}}
 async function cancel(){if(lock.current||!pending||!cancelConfirmed)return;const request=pending.request;lock.current=true;setBusy(true);setError('');setMessage('');try{await identify();if(!alive.current)return;const value=await hotelRpc('cancel_cashier_bank_action',{p_tenant:scope.tenant,p_property:scope.property,p_request:request,p_kind:'assignment',p_confirmed:true});await identify();if(!alive.current)return;const v=value as Record<string,unknown>;if(!v||v.schema_version!==1||v.tenant_id!==scope.tenant||v.property_id!==scope.property||v.actor_id!==scope.actor||v.request_id!==request||v.kind!=='assignment'||v.cancelled!==true||typeof v.replayed!=='boolean'||typeof v.created_at!=='string')throw Error('Cancellation receipt does not match the request.');const current=read();if(current&&current.request!==request)throw Error('A different request is pending.');sessionStorage.removeItem(key);if(sessionStorage.getItem(key)!==null)throw Error('Unable to clear pending request.');setPending(null);setCancelConfirmed(false);setMessage('Unrecorded assignment cancelled. Delayed retries cannot create it.')}catch(e){if(alive.current)setError(e instanceof Error?e.message:'Cancellation interrupted. Retry to confirm the result.')}finally{lock.current=false;if(alive.current)setBusy(false)}}
 return <section>{pending?<><p>Pending assignment: {pending.reason}</p><button disabled={busy} onClick={()=>void run(pending)}>Retry account assignment</button><button disabled={busy} onClick={()=>void run(pending,true)}>Check account assignment</button><label><input type="checkbox" checked={cancelConfirmed} disabled={busy} onChange={e=>setCancelConfirmed(e.target.checked)}/>Cancel this unrecorded request.</label><button disabled={busy||!cancelConfirmed} onClick={()=>void cancel()}>Cancel pending assignment</button></>:!assigned&&<details><summary>Assign bank account</summary><button disabled={busy} onClick={()=>void load()}>Find configured accounts</button>{accounts&&<>{accounts.entries.length===0?<p>Configure a bank account first.</p>:<form onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget),reason=String(f.get('reason')).trim(),account=String(f.get('account'));if(!accounts.entries.some(a=>a.id===account)||reason.length<4||reason.length>500||/[\x00-\x1f\x7f]/.test(reason)){setError('Choose an account and enter a valid explanation.');return}void run({request:crypto.randomUUID(),account,reason})}}><fieldset disabled={busy}><label>Assigned bank account<select name="account" key={accounts.entries[0]?.id}>{accounts.entries.map(a=><option key={a.id} value={a.id}>{a.label} ({a.code})</option>)}</select></label><label>Assignment explanation<input name="reason" required minLength={4} maxLength={500}/></label><label><input type="checkbox" required/>I confirm this is the account for the original deposit. This does not confirm bank receipt.</label><button>Save bank assignment</button></fieldset></form>}{accounts.next&&<button disabled={busy} onClick={()=>void load(true)}>More configured accounts</button>}</>}</details>}{error&&<p role="alert">{error}</p>}{message&&<p role="status">{message}</p>}</section>
}
